import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"Synapse — Streaming + WASM Agent + A2A Architecture (v0.2)","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-07-01-v0.2-architecture.md","filePath":"superpowers/specs/2026-07-01-v0.2-architecture.md","lastUpdated":1782896430000}'),r={name:"superpowers/specs/2026-07-01-v0.2-architecture.md"};function n(d,e,i,c,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="synapse-—-streaming-wasm-agent-a2a-architecture-v0-2" tabindex="-1">Synapse — Streaming + WASM Agent + A2A Architecture (v0.2) <a class="header-anchor" href="#synapse-—-streaming-wasm-agent-a2a-architecture-v0-2" aria-label="Permalink to &quot;Synapse — Streaming + WASM Agent + A2A Architecture (v0.2)&quot;">​</a></h1><blockquote><p><strong>Status</strong>: Draft v0.2 — supersedes v0.1 (2026-06-30) after scope pivot on 2026-07-01 (each Agent is its own WASM module, full use of <code>a2a-rs</code> SDK, Synapse as foundation layer for Prefrontal and other downstream &quot;supervisor&quot; projects).</p><p><strong>Status</strong>: Implementation in progress on branch <code>feat/streaming-a2a</code>. See <code>2026-07-01-v0.2-status.md</code> for what&#39;s actually shipped, what&#39;s deferred, and what needs decisions before tagging v0.2.</p></blockquote><h2 id="_0-v0-2-pivot-—-what-changed" tabindex="-1">0. v0.2 pivot — what changed <a class="header-anchor" href="#_0-v0-2-pivot-—-what-changed" aria-label="Permalink to &quot;0. v0.2 pivot — what changed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>v0.1 (2026-06-30)</th><th>v0.2 (2026-07-01)</th></tr></thead><tbody><tr><td>End-to-end streaming in single process</td><td><strong>Each Agent = one independent WASM module</strong></td></tr><tr><td>A2A client/server in-process; SDK optional</td><td><strong>A2A must fully use <code>a2a-rs</code> SDK</strong></td></tr><tr><td>LLM config baked into model struct</td><td><strong>LLM config (base URL, API key, model) injected from host</strong></td></tr><tr><td>Agent is server OR client</td><td><strong>Each Agent has both inbound (consumed via A2A Server) and outbound (consumed via A2A Client) capability</strong></td></tr><tr><td>—</td><td><strong>Synapse is foundation layer; Prefrontal is one downstream supervisor</strong></td></tr><tr><td>—</td><td><strong>MSRV bump 1.75 → 1.85</strong> (a2a-rs requirement)</td></tr></tbody></table><h2 id="_1-project-positioning-recap-of-project-boundary-doc" tabindex="-1">1. Project positioning (recap of project-boundary doc) <a class="header-anchor" href="#_1-project-positioning-recap-of-project-boundary-doc" aria-label="Permalink to &quot;1. Project positioning (recap of project-boundary doc)&quot;">​</a></h2><p><strong>Synapse</strong> = foundation library (layer 2). <strong>Prefrontal</strong>, and any future supervisor / cluster project (layer 3+). <strong>shadow-</strong>* apps (layer 4).</p><p>Within Synapse we do:</p><ul><li>Streaming primitives (<code>StreamReader</code>, <code>AgentStreamEvent</code>)</li><li>LLM provider abstractions (OpenAI / Anthropic over <code>wasi::http</code> and <code>reqwest</code>)</li><li>A2A protocol wrappers around <code>a2a-rs</code> SDK</li><li>WASM agent package format &amp; runtime plumbing (<code>wasmtime</code>-based)</li></ul><p>We do <strong>not</strong> do scheduling, supervision, persistence, axum serving, auth, or UI.</p><h2 id="_2-system-overview" tabindex="-1">2. System overview <a class="header-anchor" href="#_2-system-overview" aria-label="Permalink to &quot;2. System overview&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Downstream supervisor (Prefrontal, etc.)                    │</span></span>
<span class="line"><span>│                                                              │</span></span>
<span class="line"><span>│  axum HTTP server ─ a2a-rs server ─ a2a-rs client            │</span></span>
<span class="line"><span>│                       │                │                     │</span></span>
<span class="line"><span>│                       ▼                ▼                     │</span></span>
<span class="line"><span>│             ┌──────────────────────────────────┐             │</span></span>
<span class="line"><span>│             │  Synapse WASM Runtime            │             │</span></span>
<span class="line"><span>│             │   ┌──────────┐  ┌──────────┐    │             │</span></span>
<span class="line"><span>│             │   │ agent-1  │  │ agent-2  │    │             │</span></span>
<span class="line"><span>│             │   │ .wasm    │  │ .wasm    │    │             │</span></span>
<span class="line"><span>│             │   └──────────┘  └──────────┘    │             │</span></span>
<span class="line"><span>│             └──────────────────┬──────────────┘             │</span></span>
<span class="line"><span>│                                │ wasi::http                  │</span></span>
<span class="line"><span>│                                ▼                             │</span></span>
<span class="line"><span>│                          LLM provider endpoints               │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p>Each agent WASM module exposes a fixed contract — the <strong>WASM Agent ABI</strong> — that the supervisor invokes to route inbound A2A calls and consume streaming events.</p><h2 id="_3-wasm-agent-abi" tabindex="-1">3. WASM Agent ABI <a class="header-anchor" href="#_3-wasm-agent-abi" aria-label="Permalink to &quot;3. WASM Agent ABI&quot;">​</a></h2><blockquote><p>Full reference: <code>docs/wasm-agent-abi.md</code>. Summary below.</p></blockquote><h3 id="_3-1-imports-host-→-wasm" tabindex="-1">3.1 Imports (host → WASM) <a class="header-anchor" href="#_3-1-imports-host-→-wasm" aria-label="Permalink to &quot;3.1 Imports (host → WASM)&quot;">​</a></h3><p>Synapse assumes the host provides:</p><ul><li><code>wasi:http/outgoing-handler</code> — for outbound HTTP / SSE to LLM providers</li><li>A custom <code>synapse:host/agent-config</code> with one export function <code>get_config(ptr, len) -&gt; (ptr, len)</code> returning a JSON blob with: <code>llm_base_url</code>, <code>llm_api_key</code>, <code>llm_model</code>, <code>a2a_peers[]</code></li><li>A custom <code>synapse:host/a2a-call</code> with <code>send_to_peer(peer_id, msg_ptr, msg_len, out_ptr, out_len_ptr)</code> for outbound A2A peer calls (since a2a-rs client SDK is native-only; the host executes the call and returns the response)</li></ul><h3 id="_3-2-exports-wasm-→-host" tabindex="-1">3.2 Exports (WASM → host) <a class="header-anchor" href="#_3-2-exports-wasm-→-host" aria-label="Permalink to &quot;3.2 Exports (WASM → host)&quot;">​</a></h3><p>A Synapse-compiled agent MUST export:</p><table tabindex="0"><thead><tr><th>Symbol</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>agent_card</code></td><td><code>(out_ptr: i32) -&gt; i32</code> (writes <code>AgentCard</code> JSON, returns length)</td><td>A2A discovery</td></tr><tr><td><code>stream_run</code></td><td><code>(input_ptr: i32, input_len: i32, out_handle_ptr: i32) -&gt; i32</code></td><td>Yield a stream handle for inbound <code>message/send</code> or <code>message/stream</code> calls</td></tr><tr><td><code>cancel_run</code></td><td><code>(handle: i32) -&gt; i32</code></td><td>Cancel a running stream by handle</td></tr><tr><td><code>query_task</code></td><td><code>(task_id_ptr, task_id_len, out_ptr) -&gt; i32</code></td><td>Return current task state for <code>tasks/get</code></td></tr><tr><td><code>subscribe_task</code></td><td><code>(task_id_ptr, task_id_len, out_handle_ptr) -&gt; i32</code></td><td>Subscribe to task events (server push / resubscribe semantics)</td></tr></tbody></table><p>Streaming via <strong>shared linear memory</strong>: agent writes <code>AgentStreamEvent</code> records into a host-provided ring buffer; host polls the buffer when reading the agent&#39;s outbound stream response.</p><h3 id="_3-3-memory-model" tabindex="-1">3.3 Memory model <a class="header-anchor" href="#_3-3-memory-model" aria-label="Permalink to &quot;3.3 Memory model&quot;">​</a></h3><ul><li>WASM owns linear memory.</li><li>Exports take <code>(ptr, len)</code> for input strings and a pointer where the agent may write responses.</li><li>Host pre-allocates one buffer (default 64 KiB) per stream handle for outbound <code>AgentStreamEvent</code> payloads.</li><li>ABI version stamp: each WASM image exports a <code>synapse_abi_version</code> function returning a u32; current target is <code>1</code>.</li></ul><h2 id="_4-a2a-integration" tabindex="-1">4. A2A integration <a class="header-anchor" href="#_4-a2a-integration" aria-label="Permalink to &quot;4. A2A integration&quot;">​</a></h2><h3 id="_4-1-server-side" tabindex="-1">4.1 Server side <a class="header-anchor" href="#_4-1-server-side" aria-label="Permalink to &quot;4.1 Server side&quot;">​</a></h3><ul><li><code>a2a-rs</code> v0.4 (<code>a2a-server-lf</code>) provides <code>DefaultRequestHandler</code> + <code>AgentExecutor</code> (a 2-method trait).</li><li>Synapse provides <code>SynapseAgentExecutor</code> that implements <code>AgentExecutor</code> and bridges events to <strong>whatever WASM-side execution model the supervisor decides</strong> (typically: instantiate a runtime, look up the WASM module by ID, invoke its <code>stream_run</code> export).</li></ul><h3 id="_4-2-client-side" tabindex="-1">4.2 Client side <a class="header-anchor" href="#_4-2-client-side" aria-label="Permalink to &quot;4.2 Client side&quot;">​</a></h3><ul><li><code>a2a-rs</code> v0.2 (<code>a2a-client-lf</code>) provides <code>A2AClient&lt;T: Transport&gt;</code> with <code>A2AClientFactory</code> for protocol negotiation.</li><li><strong>Important</strong>: client SDK only has native transport. Synapse wraps client usage at the supervisor boundary — within WASM, peer calls go through the <code>synapse:host/a2a-call</code> import (defined in 3.1) which the supervisor fulfills via the native <code>A2AClient</code>.</li></ul><h3 id="_4-3-v1-capabilities-full-use-of-a2a-rs-as-user-requested" tabindex="-1">4.3 v1 capabilities (full use of a2a-rs as user requested) <a class="header-anchor" href="#_4-3-v1-capabilities-full-use-of-a2a-rs-as-user-requested" aria-label="Permalink to &quot;4.3 v1 capabilities (full use of a2a-rs as user requested)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Capability</th><th>Status</th></tr></thead><tbody><tr><td><code>message/send</code> (JSON-RPC)</td><td>✅</td></tr><tr><td><code>message/stream</code> (JSON-RPC + SSE)</td><td>✅</td></tr><tr><td><code>tasks/get</code>, <code>tasks/list</code>, <code>tasks/cancel</code></td><td>✅</td></tr><tr><td><code>tasks/subscribe</code> (with resubscribe)</td><td>✅</td></tr><tr><td><code>tasks/pushConfig</code> CRUD</td><td>✅ (opt-in)</td></tr><tr><td><code>agent-card.json</code> discovery</td><td>✅</td></tr><tr><td>Extended agent card</td><td>❌ deferred</td></tr><tr><td>gRPC / SLIMRPC bindings</td><td>❌ not in deps</td></tr></tbody></table><h2 id="_5-llm-provider-streaming" tabindex="-1">5. LLM provider streaming <a class="header-anchor" href="#_5-llm-provider-streaming" aria-label="Permalink to &quot;5. LLM provider streaming&quot;">​</a></h2><h3 id="_5-1-native-host-side" tabindex="-1">5.1 Native (host side) <a class="header-anchor" href="#_5-1-native-host-side" aria-label="Permalink to &quot;5.1 Native (host side)&quot;">​</a></h3><ul><li><code>HttpClientSse::sse_post</code> via <code>ReqwestHttpClient::execute_raw</code> — <strong>already implemented (chunk 2/3 done)</strong>.</li></ul><h3 id="_5-2-wasm-inside-agent-wasm" tabindex="-1">5.2 WASM (inside agent WASM) <a class="header-anchor" href="#_5-2-wasm-inside-agent-wasm" aria-label="Permalink to &quot;5.2 WASM (inside agent WASM)&quot;">​</a></h3><ul><li><code>WasiHttpClient</code> (already in Synapse) needs an SSE extension — <strong>NEW work needed</strong>: <code>WasiHttpClient::sse_post</code> using <code>wasi:http/types</code> stream chunks and the same shared SSE parser.</li></ul><h3 id="_5-3-messagedelta-and-agentstreamevent-already-implemented" tabindex="-1">5.3 <code>MessageDelta</code> and <code>AgentStreamEvent</code> (already implemented) <a class="header-anchor" href="#_5-3-messagedelta-and-agentstreamevent-already-implemented" aria-label="Permalink to &quot;5.3 \`MessageDelta\` and \`AgentStreamEvent\` (already implemented)&quot;">​</a></h3><p>The streaming core is platform-agnostic; Chunks 1+2+3+4 of v0.1 remain valid in v0.2.</p><h2 id="_6-configuration-injection" tabindex="-1">6. Configuration injection <a class="header-anchor" href="#_6-configuration-injection" aria-label="Permalink to &quot;6. Configuration injection&quot;">​</a></h2><p>To honor &quot;support 传入 LLM API 地址等信息&quot; (externalized config):</p><ul><li>Each agent WASM at startup calls <code>host::get_config(...)</code>.</li><li>The host supplies: <ul><li><code>llm_base_url</code> — e.g. <code>https://api.openai.com/v1</code></li><li><code>llm_api_key</code> — runtime secret, never baked into WASM</li><li><code>llm_model</code> — e.g. <code>gpt-4o</code></li><li><code>llm_extra</code> — provider-specific overrides (org ID, project, etc.)</li><li><code>a2a_peers</code> — list of <code>(name, url)</code> for outbound peer discovery</li></ul></li><li>Synapse provides a <code>synapse-agent-config</code> JSON schema + serde impl so the configuration round-trips cleanly.</li></ul><h2 id="_7-concrete-deliverables-v0-2" tabindex="-1">7. Concrete deliverables (v0.2) <a class="header-anchor" href="#_7-concrete-deliverables-v0-2" aria-label="Permalink to &quot;7. Concrete deliverables (v0.2)&quot;">​</a></h2><p>Reordering priorities to match user&#39;s instructions:</p><table tabindex="0"><thead><tr><th>#</th><th>Deliverable</th><th>Status</th></tr></thead><tbody><tr><td>1</td><td>Project boundary doc</td><td>✅ this + companion <code>2026-07-01-project-boundary.md</code></td></tr><tr><td>2</td><td>WASM Agent ABI spec</td><td>✅ in §3 above, full doc to follow</td></tr><tr><td>3</td><td>WASM compilation guide (<code>docs/wasm-compilation-guide.md</code>)</td><td>🔴 TODO</td></tr><tr><td>4</td><td><code>WasiHttpClient::sse_post</code></td><td>🔴 TODO</td></tr><tr><td>5</td><td><code>a2a-rs</code> SDK integration (Cargo.toml, MSRV bump)</td><td>🔴 TODO</td></tr><tr><td>6</td><td><code>synapse::a2a</code> module — server executor + client wrapper</td><td>🔴 TODO</td></tr><tr><td>7</td><td>Agent template (cargo workspace skeleton that produces a <code>.wasm</code>)</td><td>🔴 TODO — proposed in boundary doc</td></tr><tr><td>8</td><td>Architectural docs split: components-only in Synapse, topology in Prefrontal</td><td>🔴 TODO review pass on existing <code>docs/</code></td></tr></tbody></table><h2 id="_8-out-of-scope-for-v0-2" tabindex="-1">8. Out of scope for v0.2 <a class="header-anchor" href="#_8-out-of-scope-for-v0-2" aria-label="Permalink to &quot;8. Out of scope for v0.2&quot;">​</a></h2><ul><li>Persistent task stores (sqlite/postgres) — <code>InMemoryTaskStore</code> only.</li><li>Auth implementations (OAuth2/API-key) — <code>CallInterceptor</code> hook exposed.</li><li>WASM-side A2A client — peer calls go through host import.</li><li>Multi-region A2A — supervisor concern.</li></ul><h2 id="_9-migration-from-v0-1" tabindex="-1">9. Migration from v0.1 <a class="header-anchor" href="#_9-migration-from-v0-1" aria-label="Permalink to &quot;9. Migration from v0.1&quot;">​</a></h2><ul><li>Existing <code>docs/superpowers/specs/2026-06-30-streaming-design.md</code> remains a useful reference for Chunks 1–4 (Streaming core), but its §6 (Provider streaming), §7 (Agent streaming), §9 (A2A), §11 (Migration) sections are superseded by this v0.2 doc.</li><li>Chunks 1–4 <strong>landed</strong> (foundation). The MultiAgent supervisors (v0.1 Chunk 5) are <strong>superseded</strong> by the WASM-per-agent architecture; deletion is fine since they are reference patterns re-implemented by Prefrontal.</li></ul>`,47)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
